/// <summary>
/// CustTable associated with CustomerAccount field
/// </summary>
/// <returns>CustTable record if found, null otherwise</returns>
public CustTable custTable()
{
    return CustTable::find(this.CustomerAccount);
}

/// <summary>
/// VenTable record associated with VendorAccount field
/// </summary>
/// <returns>VendTable record if found, null otherwise</returns>
public VendTable vendTable()
{
    return VendTable::find(this.VendorAccount);
}

    /// <summary>
    /// Set default value on the table fields
    /// </summary>
    public void initValue()
    {
        // CB411_412_ChargeThrough currency set from vendor, moved to initFromVendTable
        //this.CurrencyCode = Ledger::accountingCurrency(CompanyInfo::current());
        this.TransactionDate =  DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        // CB194_ChargeThroughClaims
        this.ClaimStatus = METReturnStatus::NotRequired;

        super();
    }

    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(METCBCTInvoiceHeaderTable, CustomerAccount):
                this.initFromCustTable(this.custTable());
                this.assignFinancialDimension();
                this.setDueDates();
                break;
            case fieldNum(METCBCTInvoiceHeaderTable, VendorAccount):
                this.initFromVendTable(this.vendTable());
                this.assignFinancialDimension();
                this.setDueDates();
                break;
            case fieldNum(METCBCTInvoiceHeaderTable,CustPaymTermId):
            case fieldNum(METCBCTInvoiceHeaderTable,VendPaymTermId):
                this.setDueDates();
                break;

            case fieldNum(METCBCTInvoiceHeaderTable, CustWETNetAmountExclWETAndGST):
            case fieldNum(METCBCTInvoiceHeaderTable, CustWETNETAmountExclGST):
            case fieldNum(METCBCTInvoiceHeaderTable, WETNetAmountExclWETAndGST):
            case fieldNum(METCBCTInvoiceHeaderTable, WETNetAmountExclGST):
                METLegalEntityType legalEntityType = CompanyInfo::find().METLegalEntityType;
                switch(legalEntityType)
                {
                    case METLegalEntityType::Liquor:
                        this.initializeCustVendNETAmount();
                }
                break;

            case fieldNum(METCBCTInvoiceHeaderTable, VendInvoiceGSTAmount):
            case fieldNum(METCBCTInvoiceHeaderTable, WETTaxAmount):
                this.initializeGSTAmount();
                break;

            case fieldNum(METCBCTInvoiceHeaderTable, VendNetAmount):
                if (CompanyInfo::find().METLegalEntityType == METLegalEntityType::Food)
                {
                    this.CustNetAmount = this.VendNetAmount;
                }
                break;

            // Bug 287867: CB131 PBMSQA :- Error message not displayed in D365 when vendor invoice amount > 25,000 AUD
            // if the error field is changed to No, clear the error description field
            case fieldNum(METCBCTInvoiceHeaderTable, Error):
                if (!this.Error)
                {
                    this.ErrorDescription = '';
                }
                break;
        }
    }

    /// <summary>
    /// Initialize customer net amount, which is the sum of WET net amount and vendor net amount, 
    /// and also initialize WET net amount for customer based on the WET net amount for vendor.
    /// </summary>
    public void initializeCustVendNETAmount()
    {
        METLegalEntityType legalEntityType = CompanyInfo::find().METLegalEntityType;

        if (legalEntityType == METLegalEntityType::Liquor)
        {
            this.VendNetAmount                  = this.WETNETAmountExclGST + this.WETNetAmountExclWETAndGST;
        }

        this.CustWETNetAmountExclWETAndGST  = this.WETNetAmountExclWETAndGST;
        this.CustWETNETAmountExclGST        = this.WETNetAmountExclGST;

        if (legalEntityType == METLegalEntityType::Liquor)
        {
            this.CustNetAmount                  = this.CustWETNetAmountExclWETAndGST + this.CustWETNETAmountExclGST;
        }
        else if (legalEntityType == METLegalEntityType::Food)
        {
            this.CustNetAmount                  = this.VendNetAmount;
        }
        
        this.calcTotalCustomerInvoice();
    }

    /// <summary>
    /// Initialize GST amount based on WET tax amount and vendor net amount with a fixed GST rate of 10%. 
    /// This is based on the assumption that all WET amounts are GST applicable and all vendor net amounts are GST applicable. 
    /// If either of them is not zero, GST amount will be calculated; otherwise, GST amount will be set to zero.
    /// </summary>
    public void initializeGSTAmount()
    {
        this.CustGSTAmount = this.VendInvoiceGSTAmount;

        this.calcTotalCustomerInvoice();
    }

    /// <summary>
    /// Returns the GST amount formatted to three decimal places.
    /// </summary>
    [SysClientCacheDataMethodAttribute(true)]
    display TaxAmount displayCustGSTAmount()
    {
        real gstRate = 0.10;
        TaxAmount custGstAmt = this.VendInvoiceGSTAmount + gstRate * this.WETTaxAmount;

        return custGstAmt;
    }

/// <summary>
/// Set financial dimension on the line.
/// </summary>
private void assignFinancialDimension()
{
    CustTable       custTable = CustTable::find(this.CustomerAccount);
    VendTable       vendTable = VendTable::find(this.VendorAccount);
    if (custTable.RecId && vendTable.RecId)
    {
        this.FinancialDimension = DimensionDefaultFacade::serviceMergeDefaultDimensions(vendTable.DefaultDimension,custTable.DefaultDimension);
    }
    else if (custTable.RecId)
    {
        this.FinancialDimension = custTable.DefaultDimension;
    }
   
}

/// <summary>
/// MPJ_37288_ChargebackChargethrough_extension functionalities(MPJ_3587)
/// Set due dates
/// </summary>
public void setDueDates()
{
    // CB411_412_ChargeThrough
    METVendParameters metVendParameters = METVendParameters::find();
    if(metVendParameters)
    {            
        if (this.CustPaymTermId)
        {
            switch(metVendParameters.CustDueDateBasis)
            {
                case METCBCTCustDueDateBasis::TransactionDate :                      
                    this.CustDueDate = PaymTerm::find(this.CustPaymTermId).due(this.TransactionDate);
                    break;
                case METCBCTCustDueDateBasis::VendorInvoiceDate :
                    this.CustDueDate = PaymTerm::find(this.CustPaymTermId).due(this.DocumentDate);
                    break;
            }
        
        }
        if (this.VendPaymTermId)
        {
            // Always using the TransactionDate
            if (this.InvoiceType == METInvoiceType::RDA)
            {
                this.VendDueDate = PaymTerm::find(this.VendPaymTermId).due(this.DocumentDate);
            }
            else
            {
                this.VendDueDate = PaymTerm::find(this.VendPaymTermId).due(this.TransactionDate);
            }
        }
    }
}

    /// <summary>
    /// Set profit centre
    /// </summary>
    /// <param name = "_defaultDimension">
    /// Dimension default value
    /// </param>
    ///  <param name = "_dimensionName">
    /// Dimension name
    /// </param>
    ///  <param name = "_dimensionValue">
    /// Dimension value
    /// </param>
    public void setCostCentre(DimensionDefault _defaultDimension,
                                Name             _dimensionName,
                                DimensionValue   _dimensionValue)
    {
        //'ProfitCentre'
        DimensionAttribute                  dimAttribute;
        DimensionAttributeValue             dimAttributeValue;
        DimensionAttributeValueSetStorage   dimStorage;

        dimStorage      = DimensionAttributeValueSetStorage::find(_defaultDimension);
        dimAttribute    = DimensionAttribute::findByName(_dimensionName);

        if (_dimensionValue)
        {
            dimAttributeValue = DimensionAttributeValue::findByDimensionAttributeAndValue(dimAttribute, _dimensionValue, true, true);
            dimStorage.addItem(dimAttributeValue);
        }
        else
        {
            dimStorage.removeDimensionAttribute(dimAttribute.RecId);
        }

        this.FinancialDimension = dimStorage.save();
    }

    /// <summary>
    /// Defaults cost centre
    /// </summary>
    /// <returns>
    /// Cost centre dimension value
    /// </returns>
    public DimensionValue defaultCostCentre()
    {
        DimensionValue                              costCentreValue;

        METCBCTCustomerSiteOffRemitCostCentreLink   customerSiteOffRemitCostCentreLink;
        InventSiteId                                inventSiteId = CustTable::find(this.CustomerAccount).InventSiteId;

        select firstonly customerSiteOffRemitCostCentreLink 
                   where customerSiteOffRemitCostCentreLink.InventSiteId == inventSiteId;

        if (customerSiteOffRemitCostCentreLink.RecId)
        {
            costCentreValue = customerSiteOffRemitCostCentreLink.CostCentre;
        }
        
        return costCentreValue;
    }

    /// <summary>
    /// Performs validation on fields
    /// </summary>
    /// <param name = "_fieldIdToCheck">
    /// Field ID for which the value need to be validated
    /// </param>
    /// <returns>
    /// Boolean value
    /// </returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);

        switch (_fieldIdToCheck)
        {
            case fieldNum(METCBCTInvoiceHeaderTable, VendorAccount):
                ret = ret && this.validateVendorAccount();
                break;
            case fieldNum(METCBCTInvoiceHeaderTable, CustomerAccount):
                ret = ret && this.validateCustomerAccount();
                break;
        }
        return ret;
    }

    /// <summary>
    /// Validates the record before writing to the database.
    /// </summary>
    /// <returns>True if the record is valid, otherwise false</returns>
    public boolean validateWrite()
    {
        boolean ret;
        #define.vend('Vendor')
        #define.cust('Customer')    

        ret = super();

        METInvoiceType invoiceType = this.InvoiceType;
        METVendTable metVendTable = METVendTable::find(this.VendorAccount);
        METCustTable metCustTable = METCustTable::find(this.CustomerAccount);

        switch (invoiceType)
        {
            case METInvoiceType::ChargeThrough:
            case METInvoiceType::ChargeThroughClaim:
                if (!metVendTable.AllowChargeThrough)
                {
                    ret = checkFailed(strFmt("@MET:ChargeThroughValidateWrite", #vend , invoiceType)) && ret;
                }
                
                if (!metCustTable.AllowChargeThrough)
                {
                    ret = checkFailed(strFmt("@MET:ChargeThroughValidateWrite", #cust , invoiceType)) && ret;
                }
                break;

            case METInvoiceType::CrossDock:
            case METInvoiceType::CrossDockClaim:
                if (!metVendTable.AllowCrossDock)
                {
                    ret = checkFailed(strFmt("@MET:ChargeThroughValidateWrite", #vend , invoiceType)) && ret;
                }
                if (!metCustTable.AllowCrossDock)
                {
                    ret = checkFailed(strFmt("@MET:ChargeThroughValidateWrite", #cust , invoiceType)) && ret;
                }
                break;

            case METInvoiceType::RDA:
                if (!metVendTable.AllowRDA)
                {
                    ret = checkFailed(strFmt("@MET:ChargeThroughValidateWrite", #vend , invoiceType)) && ret;
                }

                if (!metCustTable.AllowRDA)
                {
                    ret = checkFailed(strFmt("@MET:ChargeThroughValidateWrite", #cust , invoiceType)) && ret;
                }
                break;

            case METInvoiceType::SVR:

                if (!metVendTable.AllowSVR)
                {
                    ret = checkFailed(strFmt("@MET:ChargeThroughValidateWrite", #vend , invoiceType)) && ret;
                }
                if (!metCustTable.AllowSVR)
                {
                    ret = checkFailed(strFmt("@MET:ChargeThroughValidateWrite", #cust , invoiceType)) && ret;
                }
                break;
        }

		if (ret)
        {
            ret = this.checkDuplicateInvTypeAndInvoiceIdOnCTHeader();
        }

        return ret;
    }

    /// <summary>
    /// Check for duplicate invoice num and invoicetype
    /// </summary>    
    public boolean checkDuplicateInvTypeAndInvoiceIdOnCTHeader()
    {
        boolean duplicateCheckValidatedOnCTHeader = true;

        str dupCheckOnSavingCTHeader = VendParameters::find().METDuplicateCheckOnSavingCTHeader;

        if (strLen(dupCheckOnSavingCTHeader) == 0)
        {
            return true;
        }

        container chargeThroughInvoice = str2con(dupCheckOnSavingCTHeader, METConstants::Semicolon);

        if (conLen(chargeThroughInvoice) > 0)
        {
            if (conFind(chargeThroughInvoice, enum2Str(this.InvoiceType)))
            {
                METCBCTInvoiceHeaderTable invoiceHeaderTable;

                select firstonly RecId from invoiceHeaderTable
                    where invoiceHeaderTable.InvoiceType == this.InvoiceType
                    && invoiceHeaderTable.VendorAccount ==  this.VendorAccount
                    && invoiceHeaderTable.TaxInvoiceNum == this.TaxInvoiceNum
                    && invoiceHeaderTable.Number != this.Number;

                if (invoiceHeaderTable.RecId)
                {
                    duplicateCheckValidatedOnCTHeader = false;
                    error(strFmt("@MET:ErrorOnDuplicateFoundForCT", this.TaxInvoiceNum, this.VendorAccount));
                }
            }
        }

        return duplicateCheckValidatedOnCTHeader;
        
    }

/// <summary>
/// Validates value of selected vendor account
/// </summary>
/// <returns>
/// True if the vendor is Charge through vendor
/// </returns>
public boolean validateVendorAccount()
{
    METVendTable metVendTable = METVendTable::find(this.VendorAccount);
    return metVendTable.AllowChargeThrough || metVendTable.AllowCrossDock || metVendTable.AllowRDA || metVendTable.AllowSVR
            ? true : checkFailed("@MET:VendorNotPermittedForChargethrough");
}

/// <summary>
/// Validates value of selected customer account
/// </summary>
/// <returns>
/// True if the customer has signed up for the Charge through process
/// </returns>
public boolean validateCustomerAccount()
{
    METCustTable metCustTable = METCustTable::find(this.CustomerAccount);
    return metCustTable.AllowChargeThrough || metCustTable.AllowCrossDock || metCustTable.AllowRDA || metCustTable.AllowSVR
           ? true : checkFailed("@MET:CustomerNotValidForChargethrough");
}

    /// <summary>
    /// MPJ-31514
    /// </summary>
    public void insert()
    {
        this.initializeCustVendNETAmount();
        this.initializeGSTAmount();
        this.assignFinancialDimension();
        this.setDueDates();

        super();

        this.autoCreateLines();
    }

