/// <summary>
/// CB411_412_ChargeThrough
/// </summary>
/// <param name = "_custTable"><c>CustTable</c> record</param>
void initFromCustTable(CustTable _custTable)
{
    this.CustPaymTermId = _custTable.PaymTermId;       
}

/// <summary>
/// CB411_412_ChargeThrough
/// </summary>
/// <param name = "_vendTable"><c>VendTable</c> record</param>
void initFromVendTable(VendTable _vendTable)
{        
    this.CurrencyCode = _vendTable.Currency;
    this.VendPaymTermId = _vendTable.PaymTermId;
}

    /// <summary>
    /// CB411_412_ChargeThrough moved from METCBCTInvoiceLinesCreation to table
    /// Calculate GST percentage
    /// </summary>
    /// <returns>
    /// return real
    /// </returns>
    public  Percent getGSTPercentage()
    {
		Percent gstPercent;
		Amount netAmount = abs(this.VendInvoiceAmtInclGST) - abs(this.VendInvoiceGSTAmount);
		if (netAmount)
		{
			gstPercent = (abs(this.VendInvoiceGSTAmount) / netAmount) * 100;

            gstPercent = round(gstPercent, 0.01);
		}
		return gstPercent;
    }

    /// <summary>
    /// CB411_412_ChargeThrough
    /// </summary>
    /// <param name = "_number">Charge through number</param>
    /// <param name = "_forupdate">Select record for update</param>
    /// <returns><c>METCBCTInvoiceHeaderTable</c> record if found; otherwise, null.</returns>
    public static METCBCTInvoiceHeaderTable find(
        METCBCTNumber   _number,
        boolean         _forupdate = false)
    {
        METCBCTInvoiceHeaderTable  invoiceHeaderTable;

        invoiceHeaderTable.selectForUpdate(_forupdate);

        if (_number)
        {
            select firstonly invoiceHeaderTable
                where invoiceHeaderTable.Number == _number;
        }

        return invoiceHeaderTable;
    }

    /// <summary>
    /// Capture errors and warnings from infolog
    /// </summary>
    /// <param name = "_from">From where to capture infolog messages</param>
    void captureFromInfolog(int _from)
    {
        SysInfologEnumerator        enumerator;
        SysInfologMessageStruct     msgStruct;
        Exception                   exceptionLocal;

        // Get error message and warning messages from infolog
        enumerator = SysInfologEnumerator::newData(infolog.copy(_from, infolog.num(0)));

        while (enumerator.moveNext())
        {
            msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
            exceptionLocal = enumerator.currentException();

            if (exceptionLocal == Exception::Error
            ||  exceptionLocal == Exception::Warning)
            {
                //errorMessage = strfmt('%1 %2', errorMessage, msgStruct.message());
                this.captureMessage(msgStruct.message());
            }
        }
    }

    /// <summary>
    /// Capture infolog message in CT ErrorDescription field
    /// </summary>
    /// <param name = "_message">Infolog message</param>
    protected void captureMessage(str _message)
    {
        if (!this.ErrorDescription)
        {
            this.ErrorDescription = _message + '\r\n';
        }
        else
        {
            this.ErrorDescription += _message + '\r\n';
        }

        this.Error = NoYes::Yes;
        this.update();
    }

    /// <summary>
    /// Method to auto create CT lines
    /// </summary>
    /// <returns>True if all lines sucessfully created; otherwise false.</returns>
    boolean autoCreateLines()
    {
        boolean ret = true;
        
        if (this.Status == METCBCTInvoiceStatus::Created)
        {
            METCBCTInvoiceLinesCreation ctInvoiceLinesCreation = METCBCTInvoiceLinesCreation::construct();
            ret = ctInvoiceLinesCreation.createMETCBCTInvoiceLine(this);

            if (FormDataUtil::isFormDataSource(this))
            {
                FormDataSource formDataSource = FormDataUtil::getFormDataSource(this);
                formDataSource.research(true);
            }
        }

        return ret;
    }

/// <summary>
/// Exist method to identify if a pending vendor invoice originated from CT
/// </summary>
/// <param name = "_invoiceId">Vendor invoice number</param>
/// <returns>true if it exists; otherwise, false.</returns>
static boolean existInvoiceId(InvoiceId _invoiceId)
{
    return _invoiceId && (select firstonly RecId from METCBCTInvoiceHeaderTable
                                                where METCBCTInvoiceHeaderTable.TaxInvoiceNum == _invoiceId).RecId != 0;
}

    /// <summary>
    /// Finds and returns the <c>METCBCTInvoiceHeaderTable</c> record associated with the specified RefFTIRecId.
    /// </summary>
    /// <param name="_refFTIInvoiceRecId">The reference FTI invoice record ID to search for.</param>
    /// <returns>The matching <c>METCBCTInvoiceHeaderTable</c> record if found; otherwise, null.</returns>
    public static METCBCTInvoiceHeaderTable findByRefFTIInvoiceId(RefRecId _refFTIInvoiceRecId)
    {
        METCBCTInvoiceHeaderTable  metCBCTInvoiceHeaderTable;

        if (_refFTIInvoiceRecId)
        {
            select firstonly metCBCTInvoiceHeaderTable
                where metCBCTInvoiceHeaderTable.RefFTIRecId == _refFTIInvoiceRecId;
        }

        return metCBCTInvoiceHeaderTable;
    }

/// <summary>
/// Calculate total customer invoice amount
/// </summary>
public void calcTotalCustomerInvoice()
{
     this.TotalCustomerInvoice = this.CustNetAmount + this.WETTaxAmount + this.displayCustGSTAmount();
}

/// <summary>
/// Update method.
/// </summary>
public void update()
{
    this.initializeCustVendNETAmount();
    this.initializeGSTAmount();
    super();
}
